source("pre.R")
cat("--- struct first/last through loop path in DEFAULT executor\n")
s <- zutable(id = c(1L, 1L, 2L), st = data.frame(a = c(1L, 2L, 3L), b = c("x", "y", "z")))
r <- try_(s[by = id, select = .(f = first(st), l = last(st), m = r(sum(a <- id), int32))]); str(as.data.frame(r))
r <- try_(s[by = id, select = .(f = first(st), l = last(st))]); str(as.data.frame(r))
r <- try_(s[select = .(id, w = over(first(st), by = id))]); str(as.data.frame(r))
ref({r <- try_(s[select = .(id, w = over(first(st), by = id))]); str(as.data.frame(r))})
r <- try_(s[select = .(id, w = over(last(st), by = id), q = r(id, int32))]); str(as.data.frame(r))
s2 <- copy(s); r <- try_(s2[, st := last(st), by = id]); str(as.data.frame(s2))
s3 <- copy(s); ref(try_(s3[, st := last(st), by = id])); str(as.data.frame(s3))
s4 <- copy(s); try_(s4[id == 1L, st := last(st)]); str(as.data.frame(s4))
cat("--- class without `[` method\n")
register_extension_type("example.celsius", structure(double(), class = "celsius"), float64)
ce <- structure(c(1.5, NA, 3), class = "celsius"); z <- zutable(t = ce, i = 1:3)
for (q in list(quote(z[i > 1]), quote(z[2:3]), quote(z[order = desc(i)]), quote(z[limit = 2]), quote(z[select = .(t)]), quote(z[by = i, select = .(f = first(t))]), quote(join(z, z, on = i, suffix = c("", "2"))), quote(rbind(z, z)), quote(z[distinct = TRUE]), quote(copy(z)), quote(z[select = .(n = is.na(t))]), quote(head(z, 2)))) { cat(deparse(q), ": "); r <- try_(eval(q)); v <- tryCatch({schema(r); "valid"}, error = function(e) "INVALID TABLE"); cat(v, "\n") }
rc <- structure(c(1.5, NA, 3), class = "myclass"); z <- zutable(t = rc, i = 1:3); print(schema(z))
for (q in list(quote(z[i > 1]), quote(z[2:3]), quote(z[order = desc(i)]), quote(z[select = .(t, i)]), quote(join(z, z, on = i, suffix = c("", "2"))), quote(rbind(z, z)), quote(head(z, 2)))) { cat(deparse(q), ": "); r <- try_(eval(q)); v <- tryCatch({schema(r); "valid"}, error = function(e) "INVALID TABLE"); cat(v, "\n") }
cat("--- r(), case, ifelse\n")
w <- zutable(a = c(1L, NA, 3L), b = c(1.5, 2.5, NA), s = c("x", "y", NA))
print(try_(w[select = .(r1 = r(a * 2L, int32), r2 = r(paste(s, a), string), r3 = r(1, float64), r4 = r(nchar(s), int32))]))
print(try_(w[select = .(r1 = r(a * 2, int32))])); print(try_(w[select = .(r1 = r(a[1:2], int32))])); print(try_(w[r(a > 1, bool)])); print(try_(w[by = s, select = .(m = r(sum(a), int32))]))
print(try_(w[select = .(c1 = case(a > 1L ~ "big", is.na(a) ~ "none", .default = "small"), c2 = case(a > 1L ~ 1), c3 = case(a > 1L ~ b, .default = 0), c4 = ifelse(a > 1L, 1, 2.5), c5 = ifelse(is.na(a), NA, a), c6 = coalesce(a, 0L), c7 = coalesce(b, a))]))
print(try_(w[select = .(c4 = ifelse(a > 1L, 1L, 2.5))])); print(try_(w[select = .(c4 = ifelse(a > 1L, 2.5, 1L))])); print(try_(w[select = .(c = case(a > 1L ~ 1L, .default = 2.5))])); print(try_(w[select = .(c = coalesce(a, 0.5))])); print(try_(w[select = .(c = a + 0.5, d = a == 1.5, e = a %in% c(1, 3), f = b %in% 1:3, g = between(a, 1, 2.5), h = between(b, 1L, 3L))]))
print(try_(w[select = .(c = a %in% c(1.5))])); print(try_(w[select = .(c = a %in% c(1, NA))])); print(try_(w[select = .(c = a %in% integer())])); print(try_(w[select = .(c = s %in% character(), d = !(s %in% "x"))])); print(try_(w[select = .(c = a %in% NULL)]))
print(try_(w[select = .(a = a == 1, b = a == 1.5, c = a < 2^31, d = a == "1", e = b == 1L, f = s == 1)]))
